а" КОГДА ЕПСБУОстатки.Субконто1 ССЫЛКА Справочник.ОсновныеСредства ТОГДА "Основное средство" КОГДА ЕПСБУОстатки.Субконто2 ССЫЛКА Справочник.ОсновныеСредства ТОГДА "Основное средство" КОГДА ЕПСБУОстатки.Субконто3 ССЫЛКА Справочник.ОсновныеСредства ТОГДА "Основное средство" КОГДА ЕПСБУОстатки.Субконто1 ССЫЛКА Справочник.БСО ТОГДА "БСО" КОГДА ЕПСБУОстатки.Субконто2 ССЫЛКА Справочник.БСО ТОГДА "БСО" КОГДА ЕПСБУОстатки.Субконто3 ССЫЛКА Справочник.БСО ТОГДА "БСО" КОНЕЦ) КАК ВидНФА} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ МАКСИМУМ(ИнвентарныеНомераОС.Ссылка) КАК ИнвентарныйНомер, ИнвентарныеНомераОС.ОС КАК ОсновноеСредство ПОМЕСТИТЬ ВТ_ИнвентарныеНомера ИЗ Справочник.ИнвентарныеНомераОС КАК ИнвентарныеНомераОС ГДЕ ИнвентарныеНомераОС.Владелец = &Организация И ИнвентарныеНомераОС.ОС В (ВЫБРАТЬ ВТ_ОстаткиСубконтоСМОЛ.НФА ИЗ ВТ_ОстаткиСубконтоСМОЛ ГДЕ ВТ_ОстаткиСубконтоСМОЛ.НФА ССЫЛКА Справочник.ОсновныеСредства) И НЕ ИнвентарныеНомераОС.ПометкаУдаления И НЕ ИнвентарныеНомераОС.ОС.ГрупповойУчет
СГРУППИРОВАТЬ ПО ИнвентарныеНомераОС.ОС ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ОстаткиСубконтоСМОЛ.Организация КАК Организация, ВТ_ОстаткиСубконтоСМОЛ.ИФО КАК ИФО, ВТ_ОстаткиСубконтоСМОЛ.КФО КАК КФО, ВТ_ОстаткиСубконтоСМОЛ.КПС КАК КПС, ВТ_ОстаткиСубконтоСМОЛ.Счет КАК Счет, ВТ_ОстаткиСубконтоСМОЛ.НФА КАК НФА, ВТ_ОстаткиСубконтоСМОЛ.ЦМО_Контрагент КАК ЦМО_Контрагент, ВТ_ОстаткиСубконтоСМОЛ.ВидНФА КАК ВидНФА, ВТ_ОстаткиСубконтоСМОЛ.КоличествоОстаток КАК КоличествоОстаток, ВЫБОР КОГДА ВТ_ОстаткиСубконтоСМОЛ.СуммаОстаток = 0 ТОГДА ЕСТЬNULL(ВТ_СуммовыеОстаткиНФА.СуммаОстаток, 0) / ЕСТЬNULL(ВТ_СуммовыеОстаткиНФА.КоличествоОстаток, 1) * ВТ_ОстаткиСубконтоСМОЛ.КоличествоОстаток ИНАЧЕ ВТ_ОстаткиСубконтоСМОЛ.СуммаОстаток КОНЕЦ КАК СуммаОстаткок, ЕСТЬNULL(ВТ_ИнвентарныеНомера.ИнвентарныйНомер, "") КАК ИнвентарныйНомер {ВЫБРАТЬ Организация.*, ИФО.*, КФО.*, КПС.*, Счет.*, НФА.*, ЦМО_Контрагент.*, ВидНФА, КоличествоОстаток, СуммаОстаткок, ИнвентарныйНомер.*} ИЗ ВТ_ОстаткиСубконтоСМОЛ КАК ВТ_ОстаткиСубконтоСМОЛ ЛЕВОЕ СОЕДИНЕНИЕ ВТ_СуммовыеОстаткиНФА КАК ВТ_СуммовыеОстаткиНФА ПО ВТ_ОстаткиСубконтоСМОЛ.Организация = ВТ_СуммовыеОстаткиНФА.Организация И ВТ_ОстаткиСубконтоСМОЛ.ИФО = ВТ_СуммовыеОстаткиНФА.ИФО И ВТ_ОстаткиСубконтоСМОЛ.КФО = ВТ_СуммовыеОстаткиНФА.КФО И ВТ_ОстаткиСубконтоСМОЛ.КПС = ВТ_СуммовыеОстаткиНФА.КПС И ВТ_ОстаткиСубконтоСМОЛ.Счет = ВТ_СуммовыеОстаткиНФА.Счет И ВТ_ОстаткиСубконтоСМОЛ.НФА = ВТ_СуммовыеОстаткиНФА.НФА ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ИнвентарныеНомера КАК ВТ_ИнвентарныеНомера ПО ВТ_ОстаткиСубконтоСМОЛ.НФА = ВТ_ИнвентарныеНомера.ОсновноеСредство
